fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let nx = x.len();
    let ny = y.len();

    // Prepare two empty grids with `ny` rows each
    let mut x_grid = Vec::with_capacity(ny);
    let mut y_grid = Vec::with_capacity(ny);

    // For each element `yi` in `y`, 
    // - push a clone of `x` as the new row in `x_grid`
    // - push a row filled with `yi` of length `nx` into `y_grid`
    for &yi in &y {
        x_grid.push(x.clone());
        y_grid.push(vec![yi; nx]);
    }

    (x_grid, y_grid)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_meshgrid_basic() {
        let x = vec![1.0, 2.0, 3.0];
        let y = vec![4.0, 5.0];
        let (xg, yg) = meshgrid(x, y);

        assert_eq!(xg.len(), 2);
        assert_eq!(yg.len(), 2);

        // xg should be [[1, 2, 3], [1, 2, 3]]
        assert_eq!(xg[0], vec![1.0, 2.0, 3.0]);
        assert_eq!(xg[1], vec![1.0, 2.0, 3.0]);

        // yg should be [[4, 4, 4], [5, 5, 5]]
        assert_eq!(yg[0], vec![4.0, 4.0, 4.0]);
        assert_eq!(yg[1], vec![5.0, 5.0, 5.0]);
    }
}